   public void replayPendingCommands() {
      for (CompactCommand command : pendingCommands) {
         if (logger.isTraceEnabled()) {
            logger.trace("Replay " + command);
         }
         try {
            command.execute();
         } catch (Exception e) {
            logger.warn(e.getMessage(), e);
